contract CreatedTest is Test {
  Created created;

  function setUp() public {
    created = new Created(10);
    console.log("Instantiated a new Created contract with initial value 10");
  }

function test_InitialValue() public view {
  require(created.x() == 10, "Initial value should be 10");
}

function test_InitialValueFAIL() public view {
  require(created.x() == 11, "Initial value should be 10");
}

function test_InitialValueFAIL_ASSERT() public view {
  assertEq(created.x(), 11, "Initial value should be 10");
}

  function test_Increment() public {
    created.increment();
    require(created.x() == 11, "Value after calling increment once should be 11");
  }

}

function test_IncrementEvents() public {
  vm.expectEmit();//you are expecting an event to be emitted
  emit CreatedWithEvent.Incremented(address(this),1);//the expected event should have type Incremneted with parameters specified
  created.increment();
  assertEq(created.x(), 11, "Value after calling increment once should be 11");

  vm.expectEmit();//you are expecting an event to be emitted
  emit CreatedWithEvent.Incremented(address(this),10);//the expected event should have type Incremneted with parameters specified
  created.incrementByArg(10);
  assertEq(created.x(), 21, "Value after calling increment with 10 should be 21");
}

function test_IncrementEventsFAIL1() public {
  vm.expectEmit();//you are expecting an event to be emitted
  emit CreatedWithEvent.Incremented(msg.sender,1);//FAIL, msg.sender is calling test, not increment
  created.increment();
  assertEq(created.x(), 11, "Value after calling increment once should be 11");

  vm.expectEmit();//you are expecting an event to be emitted
  emit CreatedWithEvent.Incremented(address(this),10);//the expected event should have type Incremneted with parameters specified
  created.incrementByArg(10);
  assertEq(created.x(), 21, "Value after calling increment with 10 should be 21");
}

