// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import {CreatedWithEvent} from "../Creator.sol";
import {Test, Vm} from "forge-std/Test.sol";

contract Ex2Test is Test {
  CreatedWithEvent created;
  address alice = makeAddr("alice");

  function setUp() public {
    created = new CreatedWithEvent(10);
  }

  // Versione corretta di test_IncrementEventsFAIL1: la chiamata la fa alice
  function test_EventFromAlice() public {
    vm.expectEmit(true, false, false, true, address(created));
    emit CreatedWithEvent.Incremented(alice, 1);
    vm.prank(alice);            // solo la PROSSIMA chiamata ha msg.sender = alice
    created.increment();

    // la chiamata successiva torna ad avere msg.sender = address(this)
    vm.expectEmit(address(created));
    emit CreatedWithEvent.Incremented(address(this), 7);
    created.incrementByArg(7);
    assertEq(created.x(), 18);
  }

  function test_RecordLogs() public {
    vm.recordLogs();
    created.increment();
    created.incrementByArg(4);
    Vm.Log[] memory logs = vm.getRecordedLogs();
    assertEq(logs.length, 2);
    // topic0 = keccak256 della firma, topic1 = from (indexed)
    assertEq(logs[0].topics[0], keccak256("Incremented(address,uint256)"));
    assertEq(address(uint160(uint256(logs[1].topics[1]))), address(this));
    assertEq(abi.decode(logs[1].data, (uint256)), 4);
  }
}

