// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import {CreatedWithEvent} from "../Creator.sol";
import {Test} from "forge-std/Test.sol";

contract Ex3Test is Test {
  CreatedWithEvent created;

  function setUp() public {
    created = new CreatedWithEvent(10);
  }

  /**
   * hardhat-config: fuzz.runs = 1000
   */
  function testFuzz_TwoIncrements(uint256 a, uint256 b) public {
    // limitiamo gli input per non andare in overflow
    a = bound(a, 0, type(uint128).max);
    b = bound(b, 0, type(uint128).max);
    created.incrementByArg(a);
    created.incrementByArg(b);
    assertEq(created.x(), 10 + a + b);
  }

  function testFuzz_OnlyEven(uint256 a) public {
    vm.assume(a % 2 == 0 && a < 1e30);  // scarta gli input dispari o enormi
    created.incrementByArg(a);
    assertEq(created.x() % 2, 0, "10 + pari deve essere pari");
  }
}

