// ===== contracts/ex/CreatorFixed.sol =====
// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.28;

import {Created} from "../Creator.sol";

contract CreatorFixed {
    address public immutable owner;
    Created public innerContract;
    event CreatedDeployed(address indexed addr, uint256 value);

    constructor() { owner = msg.sender; }

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    function overrideCreated(address arg) external onlyOwner {
        innerContract = Created(arg);
    }

    function createAndEndowCreated(uint arg) external payable returns (Created c) {
        c = new Created{value: msg.value}(arg);   // tutto il valore, niente avanzi
        innerContract = c;                         // l'indirizzo non va perso
        emit CreatedDeployed(address(c), msg.value);
    }
}

